import { createRequire } from "node:module"; const require = createRequire("C:/Users/SALEADMIN/claude-browser/x.js"); const { chromium } = require("playwright");
import { mkdirSync } from "node:fs";
const [out, bArg = "1440,768,390", aArg = "hero,tour"] = process.argv.slice(2);
mkdirSync(out, { recursive: true });
const url = "http://localhost:3100/energiegemeinschaften/software";
const browser = await chromium.launch();
for (const w of bArg.split(",").map(Number)) {
  for (let versuch = 0; versuch < 4; versuch++) {
    const page = await browser.newPage({ viewport: { width: w, height: w < 700 ? 844 : 900 } });
    const fehler = [];
    page.on("console", (m) => m.type() === "error" && fehler.push(m.text().slice(0, 200)));
    page.on("pageerror", (e) => fehler.push(String(e).slice(0, 200)));
    try {
      await page.goto(url, { waitUntil: "load", timeout: 180000 });
      await page.waitForTimeout(2500);
      await page.locator("button", { hasText: "Nur notwendige" }).first().click({ timeout: 5000 }).catch(() => {});
      for (const a of aArg.split(",")) {
        const el = page.locator(`[data-abschnitt=${a}]`).first();
        await el.scrollIntoViewIfNeeded();
        const box = await el.boundingBox();
        for (let d = 0; d < box.height; d += 300) { await page.mouse.wheel(0, 300); await page.waitForTimeout(110); }
        await page.waitForTimeout(1500);
        await page.evaluate(() => { const h = document.querySelector("header"); if (h) h.style.visibility = "hidden"; });
        await el.screenshot({ path: `${out}/w${w}-${a}.png` });
        await page.evaluate(() => { const h = document.querySelector("header"); if (h) h.style.visibility = ""; });
      }
      const sw = await page.evaluate(() => document.documentElement.scrollWidth);
      console.log(`w${w}: scrollWidth=${sw} Fehler=${fehler.length} ${fehler.join(" | ")}`);
      await page.close();
      break;
    } catch (e) { console.log(`w${w} Versuch ${versuch}: ${String(e).slice(0, 120)}`); await page.close(); await new Promise(r => setTimeout(r, 15000)); }
  }
}
await browser.close();
EOF
