        "shadow-[0_1px_0_rgba(255,255,255,0.9)_inset,0_2px_4px_-1px_rgba(3,18,43,0.08),0_18px_40px_-14px_rgba(3,18,43,0.28),0_50px_90px_-30px_rgba(3,18,43,0.45)]",
        className
      )}
    >
      <div className="flex h-9 items-center gap-2 border-b border-ink-200/70 bg-gradient-to-b from-ink-50 to-[#f3f5f8] px-3">
        <span className="flex w-[52px] shrink-0 gap-[6px]" aria-hidden="true">
          <span className="h-[9px] w-[9px] rounded-full bg-[#f2a29b] ring-1 ring-inset ring-black/5" />
          <span className="h-[9px] w-[9px] rounded-full bg-[#f3d08c] ring-1 ring-inset ring-black/5" />
          <span className="h-[9px] w-[9px] rounded-full bg-[#a9d39a] ring-1 ring-inset ring-black/5" />
        </span>
        <span className="mx-auto inline-flex min-w-0 max-w-[60%] items-center gap-1.5 truncate rounded-md bg-white px-2.5 py-[3px] text-[10.5px] font-medium text-ink-600 shadow-e1 ring-1 ring-ink-200/80">
          <Lock aria-hidden="true" className="h-2.5 w-2.5 shrink-0 text-ink-400" strokeWidth={2.5} />
          <span className="truncate">{titel}</span>
        </span>
        <span className="flex w-[52px] shrink-0 justify-end">{beispiel ? <BeispielPlakette /> : null}</span>
