}

/** Telefon-Rahmen mit Hardware-Details: Metallkante, Seitentasten, Insel, Glanz, Home-Indikator */
export function TelefonRahmen({ beispiel = true, className, children }) {
  return (
    <div
      className={cn(
        "relative rounded-[2.5rem] bg-gradient-to-b from-[#33435f] via-[#121c30] to-[#26344d] p-[3px]",
        "shadow-[0_2px_3px_rgba(3,18,43,0.35),0_30px_60px_-20px_rgba(3,18,43,0.65),0_60px_100px_-40px_rgba(3,18,43,0.7)]",
        className
      )}
    >
      {/* Seitentasten */}
      <span aria-hidden="true" className="absolute -left-[2px] top-[18%] h-[6%] w-[3px] rounded-l-sm bg-[#2b3a55]" />
      <span aria-hidden="true" className="absolute -left-[2px] top-[27%] h-[10%] w-[3px] rounded-l-sm bg-[#2b3a55]" />
